function isRealDate(text) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(text)) return false;
  const [y, m, d] = text.split('-').map(Number);
  const date = new Date(Date.UTC(y, m - 1, d));
  return date.getUTCFullYear() === y && date.getUTCMonth() === m - 1 && date.getUTCDate() === d;
}

function validateHikeForm(draft, today) {
  const errors = {};
  const name = draft.name.trim();
  if (!name) errors.name = 'Give the hike a name.';
  else if (name.length > 60) errors.name = 'Keep the name under 60 characters.';

  if (!isRealDate(draft.date)) errors.date = 'Use a real date like 2026-10-04.';
  else if (draft.date > today) errors.date = "That date hasn't happened yet.";

  const cleaned = draft.distance.trim().replace(',', '.');
  const km = Number(cleaned);
  if (!/^\d+(\.\d+)?$/.test(cleaned) || km <= 0 || km > 200) errors.distance = 'Enter a distance in km, like 8.4.';

  const duration = draft.duration.trim();
  if (duration && (!/^\d+$/.test(duration) || Number(duration) < 1 || Number(duration) > 1440)) {
    errors.duration = 'Enter whole minutes between 1 and 1440.';
  }

  if (draft.notes.length > 500) errors.notes = 'Notes are limited to 500 characters.';
  return errors;
}

const draft = { name: 'Ridge Loop', date: '2026-10-04', distance: '8,4', duration: '', notes: '' };
console.log(validateHikeForm(draft, '2026-10-05'));
